# ! [doc = " Overloadable operators."] # ! [doc = ""] # ! [doc = " Implementing these traits allows you to overload certain operators."] # ! [doc = ""] # ! [doc = " Some of these traits are imported by the prelude, so they are available in"] # ! [doc = " every Rust program. Only operators backed by traits can be overloaded. For"] # ! [doc = " example, the addition operator (`+`) can be overloaded through the [`Add`]"] # ! [doc = " trait, but since the assignment operator (`=`) has no backing trait, there"] # ! [doc = " is no way of overloading its semantics. Additionally, this module does not"] # ! [doc = " provide any mechanism to create new operators. If traitless overloading or"] # ! [doc = " custom operators are required, you should look toward macros to extend"] # ! [doc = " Rust's syntax."] # ! [doc = ""] # ! [doc = " Implementations of operator traits should be unsurprising in their"] # ! [doc = " respective contexts, keeping in mind their usual meanings and"] # ! [doc = " [operator precedence]. For example, when implementing [`Mul`], the operation"] # ! [doc = " should have some resemblance to multiplication (and share expected"] # ! [doc = " properties like associativity)."] # ! [doc = ""] # ! [doc = " Note that the `&&` and `||` operators are currently not supported for"] # ! [doc = " overloading. Due to their short circuiting nature, they require a different"] # ! [doc = " design from traits for other operators like [`BitAnd`]. Designs for them are"] # ! [doc = " under discussion."] # ! [doc = ""] # ! [doc = " Many of the operators take their operands by value. In non-generic"] # ! [doc = " contexts involving built-in types, this is usually not a problem."] # ! [doc = " However, using these operators in generic code, requires some"] # ! [doc = " attention if values have to be reused as opposed to letting the operators"] # ! [doc = " consume them. One option is to occasionally use [`clone`]."] # ! [doc = " Another option is to rely on the types involved providing additional"] # ! [doc = " operator implementations for references. For example, for a user-defined"] # ! [doc = " type `T` which is supposed to support addition, it is probably a good"] # ! [doc = " idea to have both `T` and `&T` implement the traits [`Add<T>`][`Add`] and"] # ! [doc = " [`Add<&T>`][`Add`] so that generic code can be written without unnecessary"] # ! [doc = " cloning."] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " This example creates a `Point` struct that implements [`Add`] and [`Sub`],"] # ! [doc = " and then demonstrates adding and subtracting two `Point`s."] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " use std::ops::{Add, Sub};"] # ! [doc = ""] # ! [doc = " #[derive(Debug, Copy, Clone, PartialEq)]"] # ! [doc = " struct Point {"] # ! [doc = "     x: i32,"] # ! [doc = "     y: i32,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Add for Point {"] # ! [doc = "     type Output = Self;"] # ! [doc = ""] # ! [doc = "     fn add(self, other: Self) -> Self {"] # ! [doc = "         Self {x: self.x + other.x, y: self.y + other.y}"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Sub for Point {"] # ! [doc = "     type Output = Self;"] # ! [doc = ""] # ! [doc = "     fn sub(self, other: Self) -> Self {"] # ! [doc = "         Self {x: self.x - other.x, y: self.y - other.y}"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " assert_eq!(Point {x: 3, y: 3}, Point {x: 1, y: 0} + Point {x: 2, y: 3});"] # ! [doc = " assert_eq!(Point {x: -1, y: -3}, Point {x: 1, y: 0} - Point {x: 2, y: 3});"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " See the documentation for each trait for an example implementation."] # ! [doc = ""] # ! [doc = " The [`Fn`], [`FnMut`], and [`FnOnce`] traits are implemented by types that can be"] # ! [doc = " invoked like functions. Note that [`Fn`] takes `&self`, [`FnMut`] takes `&mut"] # ! [doc = " self` and [`FnOnce`] takes `self`. These correspond to the three kinds of"] # ! [doc = " methods that can be invoked on an instance: call-by-reference,"] # ! [doc = " call-by-mutable-reference, and call-by-value. The most common use of these"] # ! [doc = " traits is to act as bounds to higher-level functions that take functions or"] # ! [doc = " closures as arguments."] # ! [doc = ""] # ! [doc = " Taking a [`Fn`] as a parameter:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " fn call_with_one<F>(func: F) -> usize"] # ! [doc = "     where F: Fn(usize) -> usize"] # ! [doc = " {"] # ! [doc = "     func(1)"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let double = |x| x * 2;"] # ! [doc = " assert_eq!(call_with_one(double), 2);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Taking a [`FnMut`] as a parameter:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " fn do_twice<F>(mut func: F)"] # ! [doc = "     where F: FnMut()"] # ! [doc = " {"] # ! [doc = "     func();"] # ! [doc = "     func();"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let mut x: usize = 1;"] # ! [doc = " {"] # ! [doc = "     let add_two_to_x = || x += 2;"] # ! [doc = "     do_twice(add_two_to_x);"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " assert_eq!(x, 5);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Taking a [`FnOnce`] as a parameter:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " fn consume_with_relish<F>(func: F)"] # ! [doc = "     where F: FnOnce() -> String"] # ! [doc = " {"] # ! [doc = "     // `func` consumes its captured variables, so it cannot be run more"] # ! [doc = "     // than once"] # ! [doc = "     println!(\"Consumed: {}\", func());"] # ! [doc = ""] # ! [doc = "     println!(\"Delicious!\");"] # ! [doc = ""] # ! [doc = "     // Attempting to invoke `func()` again will throw a `use of moved"] # ! [doc = "     // value` error for `func`"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let x = String::from(\"x\");"] # ! [doc = " let consume_and_return_x = move || x;"] # ! [doc = " consume_with_relish(consume_and_return_x);"] # ! [doc = ""] # ! [doc = " // `consume_and_return_x` can no longer be invoked at this point"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " [`clone`]: Clone::clone"] # ! [doc = " [operator precedence]: ../../reference/expressions.html#expression-precedence"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; mod arith ; mod async_function ; mod bit ; mod control_flow ; mod coroutine ; mod deref ; mod drop ; mod function ; mod index ; mod index_range ; mod range ; mod try_trait ; mod unsize ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: arith :: { Add , Div , Mul , Neg , Rem , Sub } ; #[stable (feature = "op_assign_traits" , since = "1.8.0")] pub use self :: arith :: { AddAssign , DivAssign , MulAssign , RemAssign , SubAssign } ; #[unstable (feature = "async_fn_traits" , issue = "none")] pub use self :: async_function :: { AsyncFn , AsyncFnMut , AsyncFnOnce } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: bit :: { BitAnd , BitOr , BitXor , Not , Shl , Shr } ; #[stable (feature = "op_assign_traits" , since = "1.8.0")] pub use self :: bit :: { BitAndAssign , BitOrAssign , BitXorAssign , ShlAssign , ShrAssign } ; #[stable (feature = "control_flow_enum_type" , since = "1.55.0")] pub use self :: control_flow :: ControlFlow ; #[unstable (feature = "coroutine_trait" , issue = "43122")] pub use self :: coroutine :: { Coroutine , CoroutineState } ; #[unstable (feature = "deref_pure_trait" , issue = "87121")] pub use self :: deref :: DerefPure ; #[unstable (feature = "legacy_receiver_trait" , issue = "none")] pub use self :: deref :: LegacyReceiver ; #[unstable (feature = "arbitrary_self_types" , issue = "44874")] pub use self :: deref :: Receiver ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: deref :: { Deref , DerefMut } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: drop :: Drop ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: function :: { Fn , FnMut , FnOnce } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: index :: { Index , IndexMut } ; pub (crate) use self :: index_range :: IndexRange ; #[unstable (feature = "range_into_bounds" , issue = "136903")] pub use self :: range :: IntoBounds ; #[stable (feature = "inclusive_range" , since = "1.26.0")] pub use self :: range :: { Bound , RangeBounds , RangeInclusive , RangeToInclusive } ; #[unstable (feature = "one_sided_range" , issue = "69780")] pub use self :: range :: { OneSidedRange , OneSidedRangeBound } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: range :: { Range , RangeFrom , RangeFull , RangeTo } ; #[unstable (feature = "try_trait_v2_residual" , issue = "91285")] pub use self :: try_trait :: Residual ; #[unstable (feature = "try_trait_v2_yeet" , issue = "96374")] pub use self :: try_trait :: Yeet ; pub (crate) use self :: try_trait :: { ChangeOutputType , NeverShortCircuit } ; #[unstable (feature = "try_trait_v2" , issue = "84277" , old_name = "try_trait")] pub use self :: try_trait :: { FromResidual , Try } ; #[unstable (feature = "coerce_unsized" , issue = "18598")] pub use self :: unsize :: CoerceUnsized ; #[unstable (feature = "dispatch_from_dyn" , issue = "none")] pub use self :: unsize :: DispatchFromDyn ;